export const FIELD_PRESENTATION_VERSION='field-presentation-v1';
export const FIELD_PRESENTATION_DEFAULT=Object.freeze({version:FIELD_PRESENTATION_VERSION,mode:'recover',recoveryLength:.2,endVariation:.2,relaxation:1,boundaryEmphasis:'faint'});

const exact=(value,keys)=>Object.keys(value).sort().join(',')===keys.slice().sort().join(',');
export function validateFieldPresentation(value){
 if(value===undefined)return;
 if(!value||typeof value!=='object'||Array.isArray(value)||!exact(value,['version','mode','recoveryLength','endVariation','relaxation','boundaryEmphasis'])||value.version!==FIELD_PRESENTATION_VERSION||!['recover','loose','fray','crop'].includes(value.mode)||!Number.isFinite(value.recoveryLength)||value.recoveryLength<.05||value.recoveryLength>.4||!Number.isFinite(value.endVariation)||value.endVariation<0||value.endVariation>.5||!Number.isFinite(value.relaxation)||value.relaxation<0||value.relaxation>1||!['reference','faint','hidden'].includes(value.boundaryEmphasis))throw Error('Invalid weave field presentation.');
 return value;
}
export function effectiveFieldPresentation(value){validateFieldPresentation(value);return value?structuredClone(value):{...FIELD_PRESENTATION_DEFAULT};}
export function changeFieldPresentation(value,patch){const next={...effectiveFieldPresentation(value),...patch,version:FIELD_PRESENTATION_VERSION};validateFieldPresentation(next);return next;}

const unit=(x,y)=>{const length=Math.hypot(x,y);return length?{x:x/length,y:y/length}:null;};
const point=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});
function boundaryContact(p,boundary,tolerance){for(let i=0;i<boundary.points.length;i++){const a=boundary.points[i],b=boundary.points[(i+1)%boundary.points.length],dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy);if(!length)continue;const cross=Math.abs((p.x-a.x)*dy-(p.y-a.y)*dx)/length,dot=(p.x-a.x)*dx+(p.y-a.y)*dy;if(cross<=tolerance&&dot>=-tolerance*length&&dot<=length*length+tolerance*length)return true;}return false;}
function hash(text){let value=2166136261;for(let i=0;i<text.length;i++){value^=text.charCodeAt(i);value=Math.imul(value,16777619);}return(value>>>0)/4294967295;}
function cubic(a,b,c,d,t){const u=1-t;return{x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y};}
function recovery(pointAtBoundary,neighbor,sourceDirection,length,relaxation,loose,key){const local=unit(pointAtBoundary.x-neighbor.x,pointAtBoundary.y-neighbor.y);if(!local)return[];let source=sourceDirection&&unit(sourceDirection.x,sourceDirection.y);if(source&&local.x*source.x+local.y*source.y<0)source={x:-source.x,y:-source.y};source=source||local;const target=unit(local.x*(1-relaxation)+source.x*relaxation,local.y*(1-relaxation)+source.y*relaxation)||local,end={x:pointAtBoundary.x+target.x*length,y:pointAtBoundary.y+target.y*length},normal={x:-target.y,y:target.x},side=loose?(hash(key+'|bend')*2-1)*length*.12:0,c1={x:pointAtBoundary.x+local.x*length*.34+normal.x*side,y:pointAtBoundary.y+local.y*length*.34+normal.y*side},c2={x:end.x-target.x*length*.3-normal.x*side*.25,y:end.y-target.y*length*.3-normal.y*side*.25},samples=[];for(let i=0;i<=8;i++)samples.push(cubic(pointAtBoundary,c1,c2,end,i/8));return samples;}
function extentOf(boundary){const xs=boundary.points.map(p=>p.x),ys=boundary.points.map(p=>p.y);return Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));}
function sourceDirection(strand){return strand.direction||(strand.p0&&strand.p1?{x:strand.p1.x-strand.p0.x,y:strand.p1.y-strand.p0.y}:null);}
function identity(strand,fragment,si,fi,end){return JSON.stringify([strand.family||strand.identity?.roleId,strand.strandId||strand.identity||si,fragment.fragmentId||fragment.fragmentReference||fi,end]);}

export function presentationTailStrands(strands,boundary,value){const settings=effectiveFieldPresentation(value),points=boundary?.points||[];if(points.length<3||settings.mode==='crop')return[];const extent=extentOf(boundary);if(!(extent>0))return[];const tolerance=Math.max(1e-8,extent*1e-8),result=[];for(let si=0;si<strands.length;si++){const strand=strands[si],direction=sourceDirection(strand),fragments=[];for(let fi=0;fi<strand.fragments.length;fi++){const fragment=strand.fragments[fi],source=fragment.points||[fragment.start,fragment.end];if(source.length<2)continue;for(const end of ['start','end']){const index=end==='start'?0:source.length-1,neighbor=end==='start'?source[1]:source.at(-2),p=source[index],marked=(end==='start'?fragment.startProvenance:fragment.endProvenance)?.edgeIndexes?.length>0||boundaryContact(p,boundary,tolerance);if(!marked)continue;const key=identity(strand,fragment,si,fi,end),variation=1+(hash(key)*2-1)*settings.endVariation,modeScale=settings.mode==='loose'?1.25:1,length=extent*settings.recoveryLength*variation*modeScale,curve=recovery(p,neighbor,direction,length,settings.relaxation,settings.mode==='loose',key);if(curve.length)fragments.push({...fragment,fragmentId:(fragment.fragmentId||`fragment-${fi}`)+`-presentation-${end}`,points:curve,presentationEnd:end});}}
 if(fragments.length)result.push({...strand,fragments});}
 return result;}

export function presentationTailLayers(strands,boundary,value){const settings=effectiveFieldPresentation(value),tails=presentationTailStrands(strands,boundary,settings);if(settings.mode!=='fray')return tails.length?[{opacity:1,strands:tails}]:[];const root=[],tip=[];for(const strand of tails){const a=[],b=[];for(const fragment of strand.fragments){const split=Math.max(2,Math.floor(fragment.points.length*.65)),rootPoints=fragment.points.slice(0,split+1),tipPoints=fragment.points.slice(split);if(rootPoints.length>1)a.push({...fragment,points:rootPoints});if(tipPoints.length>1)b.push({...fragment,points:tipPoints});}if(a.length)root.push({...strand,fragments:a});if(b.length)tip.push({...strand,fragments:b});}return[{opacity:.72,strands:root},{opacity:.28,strands:tip}];}

export function presentationWovenStrands(strands,boundary,value){const settings=effectiveFieldPresentation(value),tails=presentationTailStrands(strands,boundary,settings);if(settings.mode!=='fray')return tails.map(strand=>({...strand,fragments:strand.fragments.map(fragment=>({...fragment,presentationLayer:'recovery',presentationOpacity:1}))}));return tails.map(strand=>({...strand,fragments:strand.fragments.flatMap(fragment=>{const split=Math.max(2,Math.floor(fragment.points.length*.65)),root={...fragment,fragmentId:fragment.fragmentId+'-root',points:fragment.points.slice(0,split+1),presentationLayer:'root',presentationOpacity:.72},tip={...fragment,fragmentId:fragment.fragmentId+'-tip',points:fragment.points.slice(split),presentationLayer:'tip',presentationOpacity:.28};return[root,tip].filter(part=>part.points.length>1);})}));}

export function presentationTrace(strands){return{runs:strands.map(strand=>({fragments:strand.fragments.map(fragment=>fragment.points.map((_,index)=>index/(fragment.points.length-1)))}))};}

export function presentationBleedStrands(strands,boundary,value){const tails=presentationTailStrands(strands,boundary,value),byKey=new Map();for(const strand of tails)for(const fragment of strand.fragments){const key=JSON.stringify([strand.family||strand.identity?.roleId,strand.strandId||strand.identity,fragment.fragmentReference||fragment.fragmentId?.replace(/-presentation-(start|end)$/,'')]),entry=byKey.get(key)||{};entry[fragment.presentationEnd]=fragment.points;byKey.set(key,entry);}return strands.map(strand=>({...strand,fragments:strand.fragments.map(fragment=>{const source=fragment.points||[fragment.start,fragment.end],key=JSON.stringify([strand.family||strand.identity?.roleId,strand.strandId||strand.identity,fragment.fragmentReference||fragment.fragmentId]),ends=byKey.get(key)||{},points=[...(ends.start?ends.start.slice(1).reverse():[]),...source,...(ends.end?ends.end.slice(1):[])];return{...fragment,points};})}));}
